SELECT EXISTS (
    SELECT 1
    FROM organization_access.platform_role_binding
    WHERE subject_id = #{subjectId}
      AND role_code = #{roleCode}
      AND status = 'ACTIVE'
)

SELECT binding_id, subject_id, role_code, status, version, created_at, revoked_at
FROM organization_access.platform_role_binding
WHERE subject_id = #{subjectId}
  AND role_code = #{roleCode}
  AND status = 'ACTIVE'
FOR UPDATE

mapper.update:
UPDATE organization_access.platform_role_binding
SET status = 'REVOKED', version = #{version}, revoked_at = #{revokedAt}
WHERE binding_id = #{bindingId}
  AND status = 'ACTIVE'
  AND version = #{expectedVersion}
